import * as THREE from '../three.module.js';
import {batBasis,v,clamp,sweepBatObstacles} from '../physics.js';
export const BAT_PHYSICS={mass:1.18,centerOfMassY:.04,inertia:[.105,.0025,.105],gravity:9.81,gripStiffness:30000,gripDamping:180,wristStiffness:28,wristDamping:2.4,groundRestitution:.18,groundFriction:.65};
