export function poseQuaternion(p){const b=batBasis(p.yaw,p.loft,p.roll,p.twist);return new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(vector(b.right),vector(b.up),vector(b.normal).negate()));}
export function quaternionAngles(q){const normal=new THREE.Vector3(0,0,-1).applyQuaternion(q),up=new THREE.Vector3(0,1,0).applyQuaternion(q),loft=Math.asin(clamp(normal.y,-1,1)),yaw=Math.atan2(normal.x,-normal.z),base=batBasis(yaw,loft),roll=Math.atan2(-up.dot(vector(base.right)),up.dot(vector(base.up)));return {yaw,loft,roll,twist:0};}
