 const force=new THREE.Vector3(0,-c.mass*c.gravity,0),torque=new THREE.Vector3();for(const [key,y] of [['top',.56],['bottom',.465]]){const grip=this.point(v(0,y,0)),lever=grip.clone().sub(this.position),pointVelocity=this.angularVelocity.clone().cross(lever).add(this.velocity),desiredVelocity=targets[key].clone().sub(this.lastTargets[key]).divideScalar(dt).clampLength(0,15),f=targets[key].clone().sub(grip).multiplyScalar(c.gripStiffness).add(desiredVelocity.sub(pointVelocity).multiplyScalar(c.gripDamping)).multiplyScalar(strengths[key]).clampLength(0,800);force.add(f);torque.add(lever.cross(f));this.forces[key]=f.length();}
 const grip=strengths.top+strengths.bottom;if(grip>.001){const error=desiredQ.clone().multiply(this.rotation.clone().invert());if(error.w<0)error.set(-error.x,-error.y,-error.z,-error.w);const axisError=new THREE.Vector3(error.x,error.y,error.z),n=axisError.length();if(n>1e-8)axisError.multiplyScalar(2*Math.atan2(n,error.w)/n);const wristScale=grip>1?1:.22;torque.addScaledVector(axisError,c.wristStiffness*wristScale).addScaledVector(this.angularVelocity,-c.wristDamping*wristScale);}
 this.velocity.addScaledVector(force,dt/c.mass);this.angularVelocity.addScaledVector(this.inverseInertia(torque),dt).clampLength(0,45);this.position.addScaledVector(this.velocity,dt);const spin=this.angularVelocity.length();if(spin>1e-8)this.rotation.premultiply(new THREE.Quaternion().setFromAxisAngle(this.angularVelocity.clone().divideScalar(spin),spin*dt)).normalize();
 const obs=sweepBatObstacles(plain(this.position),this.lastPosition?plain(this.lastPosition):null);if(obs){const n=vector(obs.normal),relV=this.velocity.dot(n);if(relV<0){this.impulse(n.multiplyScalar(-1.3*relV*c.mass),plain(this.position));this.contacts++;}}
